/* Page templates. All dynamic/user-provided text is escaped before rendering. */
(function(root){
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tone=s=>({'Pending Review':'amber','Interview':'purple','Interview Results':'purple','Offer':'green','Rejected':'red','Hired':'green','Active':'blue','Draft':'gray','Closed':'gray','Scheduled':'purple','Completed':'green','Cancelled':'gray','Open':'amber'}[s]||'gray');
  const stageLabel=s=>s;
  const badge=s=>`<span class="badge ${tone(s)}">${e(stageLabel(s))}</span>`;
  const colors=['blue','purple','green','amber','red'];
  const avatar=c=>`<span class="avatar ${colors[(Number(c.id.split('-').pop())||0)%5]}">${e(c.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span>`;
  const button=(action,label,id='',cls='secondary',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" data-id="${e(id)}" ${extra}>${label}</button>`;
  const link=(path,label,cls='')=>`<a class="${cls}" href="#/${path}">${label}</a>`;
  const candidate=(db,a)=>db.candidates.find(c=>c.id===a.candidateId);
  const job=(db,a)=>db.jobs.find(j=>j.id===a.jobId);
  const date=d=>new Date(d.length===10?d+'T12:00:00+08:00':d).toLocaleDateString('en-SG',{timeZone:'Asia/Singapore',day:'numeric',month:'short',year:'numeric'});
  const localDay=d=>new Date(d).toLocaleDateString('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'});
  const datetime=d=>new Date(d).toLocaleString('en-SG',{timeZone:'Asia/Singapore',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
  const person=(db,a)=>{const c=candidate(db,a);return `<div class="person">${avatar(c)}<div><strong>${e(c.name)}</strong><small>${e(c.email)}</small></div></div>`;};
  const empty=(title,detail='Try changing your filters.')=>`<div class="empty">${icon('file')}<h3>${e(title)}</h3><p>${e(detail)}</p></div>`;
  const header=(title,sub='',actions='')=>`<div class="page-heading"><div><h2>${title}</h2></div><div class="heading-actions">${actions}</div></div>`;
  function assessmentRow(index,label='') {
    return `<div class="assessment-row" data-assessment-row><label>Criterion name<input name="assessmentLabel_${index}" data-assessment-label value="${e(label)}" required maxlength="80" placeholder="e.g. System design"></label><label>Rating<select name="assessmentScore_${index}" data-assessment-score required><option value="">Choose rating</option>${[1,2,3,4,5].map(value=>`<option value="${value}">${value} / 5</option>`).join('')}</select></label>${button('assessment-remove','Remove','','text-button')}</div>`;
  }
  function assessmentForm() {
    return `<section class="assessment-editor" aria-label="Assessment criteria"><h3>Assessment criteria</h3><div class="assessment-rows" data-next-assessment-id="4">${['Relevant experience','Technical skills','Communication','Teamwork'].map((label,index)=>assessmentRow(index,label)).join('')}</div>${button('assessment-add','Add criterion','','secondary compact')}<p class="assessment-scale">1 Below expectations · 2 Developing · 3 Meets expectations · 4 Strong · 5 Excellent</p></section>`;
  }
  function assessmentSummary(rows=[]) {
    return rows.length?`<dl class="assessment-results">${rows.map(row=>`<div><dt>${e(row.label)}</dt><dd>${e(row.rating)} / 5</dd></div>`).join('')}</dl>`:'';
  }
  const select=(name,values,current,label)=>`<select data-filter="${name}" aria-label="${label}">${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${e(id)}" ${current===id?'selected':''}>${e(text)}</option>`;}).join('')}</select>`;
  const search=(q,placeholder='Search work queue')=>`<label class="search">${icon('search')}<input data-search value="${e(q)}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;
  const applicationStages=[['pending-review','Pending Review'],['interview-results','Interview Results'],['rejected','Rejected'],['offer','Offer']];
  const applicationPath=stage=>'applications'+(stage?'/'+(stage==='Pending Review'?'pending-review':stage.toLowerCase().replaceAll(' ','-')):'');
  const stageForRoute=route=>route[0]==='applications'&&route[1]?HRModel.STAGES.find(s=>applicationPath(s)==='applications/'+(route[1]==='applications-review'?'pending-review':route[1])):'';
  function parseRoute(hash){
    let path;try{path=decodeURIComponent(hash.replace(/^#\/?/,''));}catch{return ['not-found'];}
    const parts=(path||'dashboard').replace(/\/+$/,'').split('/');
    if(parts[0]==='applications'&&parts[1]==='applications-review')parts[1]='pending-review';
    return parts[0]==='candidates'?['applications']:parts;
  }
  function activeApplicationStage(route,db){
    if(route[0]==='applications')return stageForRoute(route)||'';
    let a;if(['review','results'].includes(route[0]))a=db.applications.find(a=>a.id===route[1]);
    if(route[0]==='candidate')a=db.applications.find(a=>a.candidateId===route[1]&&(!route[2]||a.id===route[2]));
    if(route[0]==='success'){const event=db.activity.find(x=>x.id===route[1]);a=event&&db.applications.find(a=>a.id===event.applicationId);}
    return a?.stage||'';
  }
  function navigation(route,db){
    const page=route[0],inApplications=['applications','review','results','candidate','success'].includes(page),active=['outbox','templates','mail-log'].includes(page)?'notifications':page;
    return [['dashboard','home','Dashboard'],['applications','file','Applications'],['jobs','briefcase','Job Postings'],['interviews','calendar','Interviews'],['reports','chart','Reports'],['notifications','bell','Notifications'],['hr-profile','user','My Profile']].map(([id,ic,title])=>{
      if(id==='applications')return `<a class="nav-item ${inApplications?'active':''}" href="#/applications" ${inApplications?'aria-current="page"':''}>${icon(ic)}<span>${title}</span><span class="nav-count">${db.applications.length}</span></a>`;
      const unread=id==='notifications'?db.systemNotifications.filter(n=>!n.read).length:0;
      return `<a class="nav-item ${active===id?'active':''}" href="#/${id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${unread?`<span class="nav-count">${unread}</span>`:''}</a>`;
    }).join('');
  }
  function secondaryNavigation(route,db,ui={}){
    const page=route[0];let trail=[];
    if(['applications','review','results','candidate','success'].includes(page)){
      trail.push([page!=='applications'&&ui.returnQueue?ui.returnQueue:'applications','Applications']);
      const stage=activeApplicationStage(route,db);
      if(stage)trail.push([applicationPath(stage),stageLabel(stage)]);
      if(page==='applications'&&(stageForRoute(route)===undefined||route.length>2))trail.push(['','Queue not found']);
      if(page!=='applications')trail.push(['',{review:'Resume Review',results:'Result details',candidate:'Candidate Profile',success:'Status Updated'}[page]]);
    }else if(['notifications','outbox','templates','mail-log'].includes(page)){
      trail.push(['notifications','Notifications']);
      if(page!=='notifications')trail.push(['',{outbox:'Email Outbox',templates:'Templates','mail-log':'Logs'}[page]]);
    }else{
      const names={dashboard:'Dashboard',jobs:'Job Postings',interviews:'Interviews',reports:'Reports','hr-profile':'My Profile'};
      trail.push(['',names[page]||'Page not found']);
    }
    if(trail.length<2&&root.parent&&root.parent!==root)return '';
    return '<ol>'+trail.map(([path,label],index)=>'<li>'+(index?'<span class="breadcrumb-separator" aria-hidden="true">'+icon('right')+'</span>':'')+(index===trail.length-1?'<span class="breadcrumb-current" aria-current="page">'+e(label)+'</span>':link(path,e(label),'breadcrumb-link'))+'</li>').join('')+'</ol>';
  }
  const pageSize=(ui,kind='rows')=>kind==='cards'?(ui.compact?2:4):kind==='dashboard'?Math.max(3,(ui.pageSize||6)-3):ui.pageSize||6;
  function pageItems(items,ui,size=pageSize(ui)) {ui.page=Math.max(1,Math.min(Number(ui.page)||1,Math.ceil(items.length/size)||1));return items.slice((ui.page-1)*size,ui.page*size);}
  const pager=(ui,total,size=pageSize(ui))=>{const pages=Math.max(1,Math.ceil(total/size));return `<div class="pagination">${button('page','Previous',String(ui.page-1),'secondary compact',ui.page===1?'disabled aria-label="Previous page"':'aria-label="Previous page"')}<span>Page ${ui.page} of ${pages}</span>${button('page','Next',String(ui.page+1),'secondary compact',ui.page>=pages?'disabled aria-label="Next page"':'aria-label="Next page"')}</div>`;};
  const pageFooter=(ui,total,size=pageSize(ui),noun='records')=>`<footer class="table-footer"><p>Showing ${total?((ui.page-1)*size+1):0}–${Math.min(ui.page*size,total)} of ${total} ${noun}</p>${pager(ui,total,size)}</footer>`;
  function filtered(db,ui){return db.applications.filter(a=>{const c=candidate(db,a),j=job(db,a);return (!ui.q||(c.name+' '+c.email+' '+j.title+' '+a.id).toLowerCase().includes(ui.q.toLowerCase()))&&(!ui.job||a.jobId===ui.job)&&(!ui.stage||a.stage===ui.stage)&&(!ui.priority||a.priority===ui.priority)&&(!ui.from||a.appliedDate>=ui.from)&&(!ui.to||a.appliedDate<=ui.to);});}
  function attention(db,a){
    if(a.stage==='Pending Review'){const days=Math.max(0,Math.floor((new Date(HRModel.day())-new Date(a.appliedDate))/86400000));return ['Resume waiting '+days+' days',a.priority==='High'?'High priority':'Review requirements and experience'];}
    if(a.stage==='Interview Results')return ['Feedback received','Final decision required'];
    if(a.stage==='Offer')return a.offer.expiry<HRModel.day()?['Offer expired','Review terms or close application']:['Offer expires '+date(a.offer.expiry),a.offer.approval==='Approved'?'Ready for candidate response':'Approval required'];
    if(a.stage==='Rejected'){const messages=db.notifications.filter(n=>n.applicationId===a.id&&(n.kind==='Rejected'||(!n.kind&&(!a.retentionStartedAt||n.createdAt>=a.retentionStartedAt))));const status=messages.some(n=>n.status==='Sent')?'Notification sent':messages.some(n=>n.status==='Uncertain')?'Delivery needs checking':messages.some(n=>n.status==='Sending')?'Notification sending':messages.some(n=>n.status==='Draft')?'Notification draft prepared':'Notification not prepared';return [status,a.rejectionConfirmed?'Reason confirmed':'Confirm rejection reason'];}
    if(a.stage==='Interview')return [db.interviews.some(i=>i.applicationId===a.id&&i.status==='Scheduled')?'Interview scheduled':'Schedule required','Awaiting interview'];
    return ['Offer accepted','Hiring completed'];
  }
  const resumePath=a=>(a.stage==='Interview Results'?'results/':'review/')+a.id;
  function rowAction(a,db,expanded=false){
    const meeting=a.stage==='Interview'&&db.interviews.find(i=>i.applicationId===a.id&&i.status==='Scheduled');
    if(a.stage==='Interview'&&!meeting){const action=button('schedule','Schedule Interview',a.id,expanded?'primary compact':'secondary compact',job(db,a).status==='Active'?'':'disabled');return expanded?action+button('reject','Reject',a.id,'danger compact')+link('candidate/'+a.candidateId+'/'+a.id,'Details','button secondary compact'):action;}
    if(!expanded){const labels={'Pending Review':'View Resume','Interview Results':'View Results','Offer':'Review Offer','Rejected':'Review Rejection','Interview':'View Interview','Hired':'Details'};return ['Pending Review','Interview Results'].includes(a.stage)?link(resumePath(a),labels[a.stage],'button primary compact'):button('application',labels[a.stage],a.id,'secondary compact');}
    const c=candidate(db,a),allowed=job(db,a).status==='Active',disabled=allowed?'':'disabled';
    const profile=link('candidate/'+c.id+'/'+a.id,'Details','button secondary compact');
    const reject=button('reject','Reject',a.id,'danger compact');
    switch(a.stage){
      case 'Pending Review':return button('move-interview','Move to Interview',a.id,'primary compact',disabled)+reject+profile;
      case 'Interview':return button('application','View Interview',a.id,'primary compact')+reject+profile;
      case 'Interview Results':return link('results/'+a.id,'View Results','button primary compact')+button('offer-edit','Prepare Offer',a.id,'secondary compact',allowed&&a.feedback?'':'disabled')+reject;
      case 'Offer':return button('application','Review Offer',a.id,'primary compact')+reject+profile;
      case 'Rejected':return button('application','Review Rejection',a.id,'secondary compact')+profile;
      default:return button('application','Details',a.id,'secondary compact');
    }
  }
  function queueTable(db,items,showStage=true,expanded=false){
    return items.length?`<div class="table-scroll"><table class="${expanded?'application-table':''}"><thead><tr><th>APPLICANT</th><th>POSITION</th>${showStage?'<th>STATUS</th>':''}<th>ATTENTION NEEDED</th><th class="align-right">ACTIONS</th></tr></thead><tbody>${items.map(a=>{const t=attention(db,a),c=candidate(db,a);return `<tr><td><a href="#/${resumePath(a)}" class="applicant-resume-link" aria-label="View resume for ${e(c.name)}" title="View resume">${person(db,a)}</a></td><td class="muted">${e(job(db,a).title)}</td>${showStage?'<td>'+badge(a.stage)+'</td>':''}<td>${e(t[0])}<small class="${a.priority==='High'?'danger-text':'muted'}">${e(t[1])}</small></td><td class="align-right"><div class="row-actions">${rowAction(a,db,expanded)}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('No applications found','No applications match this queue and its filters.');
  }
  function applications(db,ui){
    const positions=select('job',[['','All positions'],...db.jobs.map(j=>[j.id,j.title])],ui.job,'Filter by position');
    const statuses=select('queue',[['','All statuses'],...HRModel.STAGES.map(stage=>[stage,stageLabel(stage)])],ui.stage,'Filter application status');
    const items=filtered(db,ui),hasFilters=ui.job||ui.priority||ui.from||ui.to||ui.q,visible=pageItems(items,ui);
    return `<section class="panel queue-panel"><div class="section-heading queue-toolbar"><div class="queue-filters">${search(ui.q,'Search applications')}${positions}${statuses}</div><div class="heading-actions">${button('export',icon('download')+'Export')+button('filters','Filters','','secondary')}</div></div>${hasFilters?'<div class="filter-strip"><span class="muted">'+[ui.priority?e(ui.priority)+' priority':'',ui.from?'From '+date(ui.from):'',ui.to?'To '+date(ui.to):''].filter(Boolean).join(' · ')+'</span>'+button('clear-filters','Clear filters','','text-button')+'</div>':''}${queueTable(db,visible,ui.reviewQueue,true)}${pageFooter(ui,items.length,pageSize(ui),'applications')}</section>`;
  }
  function scheduleCard(db,i){const a=db.applications.find(a=>a.id===i.applicationId),c=candidate(db,a);return `<button class="interview-card" data-action="interview" data-id="${i.id}"><span class="time-box purple">${e(i.time)}<small>${i.duration} MIN</small></span><span><strong>${e(c.name)}</strong><small>${e(job(db,a).title)} · ${i.duration} min</small><small>${e(i.format+' · '+i.location)}</small></span>${icon('right')}</button>`;}
  function dashboard(db,ui){
    const today=HRModel.day(),scheduled=db.interviews.filter(i=>i.status==='Scheduled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const td=scheduled.filter(i=>i.date===today),week=scheduled.filter(i=>i.date>=today&&i.date<=HRModel.day(6)),next=scheduled.find(i=>new Date(i.date+'T'+i.time+':00+08:00')>new Date());
    const recent=[...db.applications].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||b.id.localeCompare(a.id)),size=pageSize(ui,'dashboard'),apps=pageItems(recent,ui,size);
    return header('Welcome, '+e(db.currentUser?.name||'HR team'),'Your recruitment workspace at a glance.',button('job-new',icon('plus')+'Create Job Posting','','primary'))+`<div class="dashboard-grid"><section class="panel performance"><h3>Job Post Performance</h3><div class="job-stats">${db.jobs.slice(0,3).map((j,i)=>{const n=db.applications.filter(a=>a.jobId===j.id).length;return `<div class="job-stat"><span class="icon-disc ${colors[i]}">${icon(i===2?'chart':'briefcase')}</span><div><strong>${e(j.title)}</strong><small>${n} applications</small></div><b>${n}</b></div>`;}).join('')}</div></section><section class="panel overview"><div class="section-heading bare"><h3>Interview Overview</h3>${link('interviews','View calendar →','text-button')}</div><div class="interview-stats"><span class="icon-disc purple">${icon('calendar')}</span><div><small>TODAY</small><strong>${td.length}</strong></div><div><small>NEXT 7 DAYS</small><strong>${week.length}</strong></div><div class="next-stat"><small>NEXT</small><b>${next?e(next.time):'—'}</b><small>${next?e(candidate(db,db.applications.find(a=>a.id===next.applicationId)).name):'No upcoming interview'}</small></div></div></section><section class="panel"><div class="section-heading"><h3>Recent Applications</h3>${link('applications','View all applications →','text-button')}</div><div class="table-scroll"><table><thead><tr><th>CANDIDATE</th><th>POSITION</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${apps.map(a=>`<tr><td>${person(db,a)}</td><td>${e(job(db,a).title)}<small>${e(job(db,a).department+' · '+job(db,a).type)}</small></td><td>${badge(a.stage)}</td><td>${button('application','View',a.id,'secondary compact')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><p>Showing ${apps.length} of ${db.applications.length} recent applications</p>${pager(ui,db.applications.length,size)}</div></section><section class="panel schedule"><h3>Interview Schedule</h3><p class="muted">Manage upcoming candidate interviews</p><div class="segmented"><button data-action="period" data-id="today" aria-pressed="${ui.period==='today'}" class="${ui.period==='today'?'selected':''}">Today · ${td.length}</button><button data-action="period" data-id="week" aria-pressed="${ui.period==='week'}" class="${ui.period==='week'?'selected':''}">Next 7 days · ${week.length}</button></div>${(ui.period==='today'?td:week).length?(ui.period==='today'?td:week).slice(0,3).map(i=>`<p class="day-label">${date(i.date)}</p>${scheduleCard(db,i)}`).join(''):empty('No interviews scheduled',db.applications.some(a=>a.stage==='Interview')?'Schedule a candidate from the Interview queue.':'Move a candidate to Interview to start scheduling.')}${link('interviews','View Full Calendar','button soft full')}</section></div>`;
  }
  function timeline(db,id){const items=db.activity.filter(x=>x.applicationId===id);return items.length?`<ol class="timeline">${items.map(x=>`<li><strong>${e(x.summary)}</strong><small>${e(x.actor)} · ${datetime(x.at)}</small>${x.notes?`<p>${e(x.notes)}</p>`:''}</li>`).join('')}</ol>`:empty('No activity yet','Status changes and saved notes will appear here.');}
  function success(db,ui,id){
    const event=db.activity.find(x=>x.id===id),a=event&&db.applications.find(a=>a.id===event.applicationId);
    return a?root.HRReview.render([a.stage==='Interview Results'?'results':'review',a.id],db,ui):empty('Update not found','Open Applications to view the latest records.');
  }
  function profile(db,ui,id){const c=db.candidates.find(c=>c.id===id),a=db.applications.find(a=>a.candidateId===id&&(!ui.profileApplicationId||a.id===ui.profileApplicationId));if(!c)return empty('Candidate not found');if(!a)return header(e(c.name))+`<section class="panel padded"><h3>${e(c.name)}</h3><p>${e(c.email)}</p><p>${e(c.phone||'Not provided')}</p><p>${e(c.location||'Not provided')}</p><p>No applications recorded</p></section>`;const j=job(db,a),tasks=db.tasks.filter(t=>t.applicationId===a.id);return header(e(c.name),'Candidate profile and recruitment history.',link('review/'+a.id,'View Resume','button secondary')+button('application','Manage Application',a.id,'primary'))+`<div class="two-columns profile-grid"><section class="panel padded"><div class="profile-heading">${avatar(c)}<div><h3>${e(c.name)}</h3><p>${e(j.title)} Applicant</p>${badge(a.stage)}</div></div><dl class="details"><dt>Email</dt><dd>${e(c.email)}</dd><dt>Phone</dt><dd>${e(c.phone)}</dd><dt>Location</dt><dd>${e(c.location)}</dd><dt>Experience</dt><dd>${c.experience} years</dd>${c.education&&c.education!=='Not recorded'?'<dt>Education</dt><dd>'+e(c.education)+'</dd>':''}<dt>Application</dt><dd>${e(a.id)}</dd></dl><h4>Skills</h4><div class="skill-tags">${c.skills.map(s=>`<span>${e(s)}</span>`).join('')}</div><div class="section-heading bare spaced"><h4>Private candidate note</h4>${button('candidate-notes','Edit note',a.id,'text-button')}</div><div class="note-box">${e(c.notes||'No note added.')}</div></section><section class="panel padded"><div class="section-heading bare"><h3>Tasks</h3>${button('task','Create Task',a.id,'secondary compact')}</div>${tasks.length?tasks.map(t=>`<div class="task-item"><div><strong>${e(t.title)}</strong><small>${e(t.assignee)} · Due ${date(t.due)}</small>${t.notes?`<p>${e(t.notes)}</p>`:''}</div>${t.status==='Open'?button('task-complete','Complete',t.id,'secondary compact'):badge('Completed')}</div>`).join(''):empty('No follow-up tasks','Create a task to record the next action.')}<h3 class="spaced">Application Timeline</h3>${timeline(db,a.id)}</section></div>`;}
  function jobs(db,ui){
    const items=db.jobs.filter(j=>(!ui.q||(j.title+' '+j.department).toLowerCase().includes(ui.q.toLowerCase()))&&(!ui.jobStatus||j.status===ui.jobStatus)),visible=pageItems(items,ui);
    return header('Job Postings','Create and manage the roles your team is recruiting for.',button('job-new',icon('plus')+'Create Job Posting','','primary'))+`<div class="page-filters">${search(ui.q,'Search job postings')}${select('jobStatus',[['','All statuses'],'Active','Draft','Closed'],ui.jobStatus,'Filter job status')}</div><section class="panel">${items.length?`<div class="table-scroll"><table><thead><tr><th>POSITION</th><th>WORK ARRANGEMENT</th><th>STATUS</th><th>APPLICATIONS</th><th class="align-right">ACTION</th></tr></thead><tbody>${visible.map(j=>`<tr><td><strong>${e(j.title)}</strong><small>${e(j.department)}</small></td><td>${e(j.type)}<small>${e(j.location+' · '+j.mode)}</small></td><td>${badge(j.status)}</td><td>${db.applications.filter(a=>a.jobId===j.id).length}</td><td class="align-right">${button('job-edit','Edit',j.id,'secondary compact')}${button('job-applications','Applications',j.id,'secondary compact')}${button(j.status==='Closed'?'job-open':'job-close',j.status==='Closed'?'Reopen':'Close',j.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:empty('No job postings found')}${pageFooter(ui,items.length,pageSize(ui),'jobs')}</section>`;
  }
  function interviews(db,ui){const eligible=db.applications.filter(a=>a.stage==='Interview'&&job(db,a).status==='Active'&&!db.interviews.some(i=>i.applicationId===a.id&&i.status==='Scheduled'));const items=db.interviews.filter(i=>(!ui.interviewStatus||i.status===ui.interviewStatus)&&(!ui.q||candidate(db,db.applications.find(a=>a.id===i.applicationId)).name.toLowerCase().includes(ui.q.toLowerCase()))&&(!ui.interviewDate||i.date===ui.interviewDate)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const visible=pageItems(items,ui);return header('Interviews','Schedule interviews and record feedback after the meeting.',button('schedule-select',icon('plus')+'Schedule Interview','','primary'))+`<div class="page-filters">${search(ui.q,'Search interviews')}${select('interviewStatus',[['','All statuses'],'Scheduled','Completed','Cancelled'],ui.interviewStatus,'Filter interview status')}<label class="inline-label">Date<input type="date" data-filter="interviewDate" value="${e(ui.interviewDate)}"></label>${button('clear-filters','Clear filters','','text-button')}</div>${eligible.length?`<div class="waiting-summary"><span><strong>${eligible.length}</strong> applications awaiting scheduling</span>${button('schedule-select','Choose candidate','','secondary compact')}</div>`:''}<section class="panel">${items.length?`<div class="table-scroll"><table><thead><tr><th>APPLICANT</th><th>INTERVIEW STATUS</th><th>DATE & TIME</th><th>MEETING</th><th>ACTION</th></tr></thead><tbody>${visible.map(i=>{const a=db.applications.find(a=>a.id===i.applicationId);return `<tr><td><a class="applicant-resume-link" href="#/${resumePath(a)}" title="View resume">${person(db,a)}</a><small>${e(job(db,a).title)}</small></td><td>${badge(i.status)}</td><td>${date(i.date)}<small>${e(i.time)} · ${i.duration} min</small></td><td>${e(i.format)}<small>${e(i.interviewer)}</small></td><td>${button('interview','View',i.id,'secondary compact')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No interviews found','Schedule a candidate in the Interview stage, or change your filters.')}${pageFooter(ui,items.length)}</section>`;}
  function reports(db,ui){
    const total=db.applications.length,section=ui.section||'summary',tasks=db.tasks.filter(t=>t.status==='Open');
    let body;
    if(section==='jobs'){const items=pageItems(db.jobs,ui);body=`<section class="panel"><div class="table-scroll"><table><thead><tr><th>POSITION</th><th>APPLICATIONS</th><th>IN REVIEW</th><th>OFFERS</th><th>HIRED</th></tr></thead><tbody>${items.map(j=>{const apps=db.applications.filter(a=>a.jobId===j.id);return `<tr><td>${e(j.title)}</td><td>${apps.length}</td><td>${apps.filter(a=>a.stage==='Pending Review').length}</td><td>${apps.filter(a=>a.stage==='Offer').length}</td><td>${apps.filter(a=>a.stage==='Hired').length}</td></tr>`;}).join('')}</tbody></table></div>${pageFooter(ui,db.jobs.length)}</section>`;}
    else if(section==='tasks'){body=`<section class="panel padded">${pageItems(tasks,ui).map(t=>`<div class="task-item"><div><strong>${e(t.title)}</strong><small>${e(t.assignee)} · ${date(t.due)}</small></div>${button('task-complete','Complete',t.id,'secondary compact')}</div>`).join('')||empty('No open tasks','Tasks created from candidate records appear here.')}${pageFooter(ui,tasks.length)}</section>`;}
    else body=`<div class="report-stats">${[['Applications',total],['Active jobs',db.jobs.filter(j=>j.status==='Active').length],['Scheduled interviews',db.interviews.filter(i=>i.status==='Scheduled').length],['Hired',db.applications.filter(a=>a.stage==='Hired').length]].map(([name,n])=>`<section class="panel padded"><p class="muted">${name}</p><strong class="big-number">${n}</strong></section>`).join('')}</div><section class="panel padded"><h3>Applications by stage</h3><div class="stage-bars">${HRModel.STAGES.map(s=>{const n=db.applications.filter(a=>a.stage===s).length;return `<div><div><span>${stageLabel(s)}</span><strong>${n}</strong></div><div class="bar-track"><span class="${tone(s)}" style="width:${total?n/total*100:0}%"></span></div></div>`;}).join('')}</div></section>`;
    return header('Reports','Recruitment totals calculated from this workspace.',button('export-report',icon('download')+'Export Report','','primary'))+`<nav class="section-tabs" aria-label="Report sections">${[['summary','Overview'],['jobs','Job performance'],['tasks','Follow-up tasks']].map(([id,label])=>button('section',label,id,section===id?'selected':'',`aria-pressed="${section===id}"`)).join('')}</nav>`+body;
  }
  function notifications(db,ui){const items=db.notifications.filter(n=>(ui.noticeTab!=='unread'||!n.read)&&(!ui.q||(n.subject+' '+n.to).toLowerCase().includes(ui.q.toLowerCase())));return header('Notifications','Review email drafts and candidate communications.',button('read-all','Mark all as read','','secondary'))+`<div class="notice blue info-notice">${icon('mail')}<p>Review drafts in Email Outbox before sending.</p></div><div class="page-filters">${search(ui.q,'Search notifications')}${select('noticeTab',[['all','All drafts'],['unread','Unread']],ui.noticeTab,'Filter notifications')}</div><section class="panel">${items.length?items.map(n=>`<article class="notification-item ${n.read?'':'unread'}"><span class="icon-disc blue">${icon('mail')}</span><div><strong>${e(n.subject)}</strong><p>${e(n.to)}</p><small>${datetime(n.createdAt)} · ${e(n.status)}, not sent</small></div><div class="card-actions">${button('message-edit','View draft',n.id,'secondary compact')}${!n.read?button('notice-read','Mark read',n.id,'text-button'):''}</div></article>`).join(''):empty('No notifications','Prepare an email from an application to add it to the outbox.')}</section>`;}
  root.HRViews={assessmentRow,assessmentForm,assessmentSummary,e,tone,stageLabel,resumePath,badge,avatar,button,link,candidate,job,date,datetime,localDay,person,empty,header,select,search,pageSize,pageItems,pageFooter,pager,filtered,attention,timeline,applicationStages,applicationPath,stageForRoute,parseRoute,activeApplicationStage,navigation,secondaryNavigation,render(route,db,ui){const [page,id]=route;switch(page){case 'dashboard':return dashboard(db,ui);case 'applications':{const stage=stageForRoute(route);if(stage===undefined||route.length>2)return empty('Queue not found','Open Applications and choose a status from the filter.');ui.reviewQueue=!route[1];ui.stage=stage;return applications(db,ui);}case 'review':case 'results':return root.HRReview.render(route,db,ui);case 'success':return success(db,ui,id);case 'candidates':return applications(db,{...ui,stage:''});case 'candidate':return profile(db,ui,id);case 'jobs':return jobs(db,ui);case 'interviews':return interviews(db,ui);case 'reports':return reports(db,ui);case 'notifications':return notifications(db,ui);default:return empty('Page not found','Choose a page from the sidebar.');}}};
})(window);
